export default function read({ body, stateId, labelId, teams }) {
  const d = body || {},
    id = String(d.id || ""),
    revision = String(d.updatedAt || "");
  if (!id || !revision) throw Error("Linear issue ID and updatedAt required");
  const labels = Array.isArray(d.labels?.nodes)
    ? d.labels.nodes
    : Array.isArray(d.labels)
      ? d.labels
      : [];
  const eligible =
    typeof d.description === "string" &&
    !d.description.includes("Add a description here") &&
    d.state?.id === stateId &&
    labels.some((x) => x.id === labelId);
  return {
    eligible,
    id,
    revision,
    prompt: JSON.stringify({ title: d.title, description: d.description, teams }),
  };
}

