export default async function plan({ body, id, revision, answer, acknowledge, resolution }, ctx) {
  if (body.errors?.length || !Array.isArray(body.data?.teams?.nodes))
    throw Error("Linear teams query failed");
  const name = String(answer || "").trim(),
    matches = body.data.teams.nodes.filter((t) => t.name === name);
  if (name !== "Other" && matches.length !== 1)
    throw Error("Model must select an exact unique Linear team or Other");
  const key = "triage:" + id + ":" + revision,
    old = await ctx.state.get(key);
  if (old?.status === "done")
    return { run: false, other: false, key, issueId: id, teamId: "", text: "" };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending Linear update or Slack notification " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { run: false, other: false, key, issueId: id, teamId: "", text: "" };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    run: true,
    other: name === "Other",
    key,
    issueId: id,
    teamId: matches[0]?.id ?? "",
    text: "The AI was not able to identify a fitting team for a bug",
  };
}

